#include <system_error>
#include <iostream>
int main() {
    std::error_code ec(ENOENT, std::system_category());  // Creates an error_code for 'no such file or directory'
    if (ec) {  // Implicit conversion to bool checks if m_val != 0
        std::cout << "Error: " << ec.value() << " - " << ec.message() << std::endl;  // ec.value() accesses m_val; ec.message() calls a virtual function on m_cat
    }
    return 0;
}
